#include "launcher/LlamaManager.h"
#include "port/PortChecker.h"
#include <filesystem>
namespace lvk::launcher { namespace { std::wstring q(const std::filesystem::path&p){return L"\""+p.wstring()+L"\"";} } std::wstring LlamaManager::commandLine(const config::Settings&s,const config::Profile&p)const{return L"serve -m "+q(p.model)+L" -c "+std::to_wstring(p.context)+L" -np "+std::to_wstring(p.parallel)+L" -ngl "+std::to_wstring(p.gpuLayers)+L" -ncmoe "+std::to_wstring(p.cpuMoe)+L" --temp "+std::to_wstring(p.temperature)+L" --presence-penalty "+std::to_wstring(p.presencePenalty)+L" --repeat-penalty "+std::to_wstring(p.repeatPenalty)+L" --frequency-penalty "+std::to_wstring(p.frequencyPenalty)+L" -ctk "+std::wstring(p.kvK.begin(),p.kvK.end())+L" -ctv "+std::wstring(p.kvV.begin(),p.kvV.end())+L" -fa "+(p.flashAttention?L"on":L"off")+L" --tools "+std::wstring(p.tools.begin(),p.tools.end())+L" --tools-runtime "+std::wstring(p.toolsRuntime.begin(),p.toolsRuntime.end())+L" --host "+std::wstring(s.host.begin(),s.host.end())+L" --port "+std::to_wstring(s.port);}
bool LlamaManager::start(const config::Settings&s,const config::Profile&p,std::string&e){if(running()){e="llama server is already running.";return false;}if(!std::filesystem::is_regular_file(p.model)){e="GGUF model file not found.";return false;}const std::wstring exe=std::wstring(s.llamaCommand.begin(),s.llamaCommand.end());if(!process_.start(exe,commandLine(s,p),{},[this](const std::string&x){log_.write(x);})){e="Could not start llama serve. Check llama_command and its permissions.";return false;}return true;}bool LlamaManager::stop(){return process_.stop();}bool LlamaManager::running()const{return process_.running();} }
